module EICG_wrapper (
	out,
	en,
	test_en,
	in
);
	output out;
	input en;
	input test_en;
	input in;
	reg en_latched;
	always @(*)
		if (!in)
			en_latched = en || test_en;
	assign out = en_latched && in;
endmodule
module GenericAnalogIOCell (
	pad,
	core
);
	inout pad;
	inout core;
	assign core = 1'bz;
	assign pad = core;
endmodule
module GenericDigitalGPIOCell (
	pad,
	i,
	ie,
	o,
	oe
);
	inout pad;
	output i;
	input ie;
	input o;
	input oe;
	assign pad = (oe ? o : 1'bz);
	assign i = (ie ? pad : 1'b0);
endmodule
module GenericDigitalInIOCell (
	pad,
	i,
	ie
);
	input pad;
	output i;
	input ie;
	assign i = (ie ? pad : 1'b0);
endmodule
module GenericDigitalOutIOCell (
	pad,
	o,
	oe
);
	output pad;
	input o;
	input oe;
	assign pad = (oe ? o : 1'bz);
endmodule

