module SRAM1RW64x128_1bit (
	CE_i,
	WEB_i,
	A_i,
	OEB_i,
	CSB_i,
	I_i,
	O_i
);
	input CSB_i;
	input OEB_i;
	input CE_i;
	input WEB_i;
	input [5:0] A_i;
	input [0:0] I_i;
	output reg [0:0] O_i;
	reg [0:0] memory [63:0];
	reg [0:0] data_out;
	wire RE;
	wire WE;
	and u1 (RE, ~CSB_i, WEB_i);
	and u2 (WE, ~CSB_i, ~WEB_i);
	always @(posedge CE_i)
		if (RE)
			data_out = memory[A_i];
	always @(posedge CE_i)
		if (WE)
