module SRAM2RW16x16_1bit (
	CE1_i,
	CE2_i,
	WEB1_i,
	WEB2_i,
	A1_i,
	A2_i,
	OEB1_i,
	OEB2_i,
	CSB1_i,
	CSB2_i,
	I1_i,
	I2_i,
	O1_i,
	O2_i
);
	input CSB1_i;
	input CSB2_i;
	input OEB1_i;
	input OEB2_i;
	input CE1_i;
	input CE2_i;
	input WEB1_i;
	input WEB2_i;
	input [3:0] A1_i;
	input [3:0] A2_i;
	input [0:0] I1_i;
	input [0:0] I2_i;
	output reg [0:0] O1_i;
	output reg [0:0] O2_i;
	reg [0:0] memory [15:0];
	reg [0:0] data_out1;
	reg [0:0] data_out2;
	wire RE1;
	wire WE1;
	wire RE2;
	wire WE2;
	and u1 (RE1, ~CSB1_i, WEB1_i);
	and u2 (WE1, ~CSB1_i, ~WEB1_i);
	and u3 (RE2, ~CSB2_i, WEB2_i);
	and u4 (WE2, ~CSB2_i, ~WEB2_i);
	always @(posedge CE1_i)
		if (RE1)
			data_out1 = memory[A1_i];
	always @(posedge CE1_i)
		if (WE1)
			memory[A1_i] = I1_i;
	always @(data_out1 or OEB1_i)
		if (!OEB1_i)
			O1_i = data_out1;
		else
			O1_i = 1'bz;
	always @(posedge CE2_i)
		if (RE2)
			data_out2 = memory[A2_i];
	always @(posedge CE2_i)
		if (WE2)
			memory[A2_i] = I2_i;
	always @(data_out2 or OEB2_i)
		if (!OEB2_i)
			O2_i = data_out2;
		else
			O2_i = 1'bz;
endmodule
