	io_deq_bits_mask,
	io_deq_bits_corrupt
);
	input clock;
	input reset;
	input io_repeat;
	output io_full;
	output io_enq_ready;
	input io_enq_valid;
	input [2:0] io_enq_bits_opcode;
	input [2:0] io_enq_bits_param;
	input [2:0] io_enq_bits_size;
	input [2:0] io_enq_bits_source;
	input [16:0] io_enq_bits_address;
	input [7:0] io_enq_bits_mask;
	input io_enq_bits_corrupt;
	input io_deq_ready;
	output io_deq_valid;
	output [2:0] io_deq_bits_opcode;
	output [2:0] io_deq_bits_param;
	output [2:0] io_deq_bits_size;
	output [2:0] io_deq_bits_source;
	output [16:0] io_deq_bits_address;
	output [7:0] io_deq_bits_mask;
	output io_deq_bits_corrupt;
	reg full;
	reg [2:0] saved_opcode;
	reg [2:0] saved_param;
	reg [2:0] saved_size;
	reg [2:0] saved_source;
	reg [16:0] saved_address;
	reg [7:0] saved_mask;
	reg saved_corrupt;
	wire _T = io_enq_ready & io_enq_valid;
	wire _GEN_0 = (_T & io_repeat) | full;
	wire _T_2 = io_deq_ready & io_deq_valid;
	assign io_full = full;
	assign io_enq_ready = io_deq_ready & ~full;
	assign io_deq_valid = io_enq_valid | full;
	assign io_deq_bits_opcode = (full ? saved_opcode : io_enq_bits_opcode);
	assign io_deq_bits_param = (full ? saved_param : io_enq_bits_param);
	assign io_deq_bits_size = (full ? saved_size : io_enq_bits_size);
	assign io_deq_bits_source = (full ? saved_source : io_enq_bits_source);
	assign io_deq_bits_address = (full ? saved_address : io_enq_bits_address);
	assign io_deq_bits_mask = (full ? saved_mask : io_enq_bits_mask);
	assign io_deq_bits_corrupt = (full ? saved_corrupt : io_enq_bits_corrupt);
	always @(posedge clock) begin
		if (reset)
			full <= 1'h0;
		else if (_T_2 & ~io_repeat)
			full <= 1'h0;
		else
			full <= _GEN_0;
		if (_T & io_repeat)
			saved_opcode <= io_enq_bits_opcode;
		if (_T & io_repeat)
			saved_param <= io_enq_bits_param;
		if (_T & io_repeat)
			saved_size <= io_enq_bits_size;
		if (_T & io_repeat)
