	wire [11:0] rawA_exp = io_a[63:52];
	wire rawA_isZero = rawA_exp[11:9] == 3'h0;
	wire rawA_isSpecial = rawA_exp[11:10] == 2'h3;
	wire rawA__isNaN = rawA_isSpecial & rawA_exp[9];
	wire rawA__isInf = rawA_isSpecial & ~rawA_exp[9];
	wire rawA__sign = io_a[64];
	wire [12:0] rawA__sExp = {1'b0, $signed(rawA_exp)};
	wire _rawA_out_sig_T = ~rawA_isZero;
