module PlusArgTimeout (
	clock,
	reset,
	io_count
);
	input clock;
	input reset;
	input [31:0] io_count;
	wire [31:0] plusarg_reader_out;
	wire _T = plusarg_reader_out > 32'h00000000;
	
	always @(posedge clock) begin
		if (~(io_count < plusarg_reader_out) & (_T & ~reset))
			$fatal;
		if ((_T & ~reset) & ~(io_count < plusarg_reader_out))
			$fwrite(32'h80000002, "Assertion failed: Timeout exceeded: Kill the emulation after INT rdtime cycles. Off if 0.\n    at PlusArg.scala:64 assert (io.count < max, s\"Timeout exceeded: $docstring\")\n");
	end
endmodule
