module AsyncResetRegVec_w1_i0_5 (
	clock,
	reset,
	io_d,
	io_q,
	io_en
);
	input clock;
	input reset;
	input io_d;
	output io_q;
	input io_en;
	reg reg_;
	assign io_q = reg_;
	always @(posedge clock or posedge reset)
